INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'barbarian'), 'Path of the Berserker', 'path-of-the-berserker', 'Barbarians who walk the Path of the Berserker direct their Rage primarily toward violence. Their path is one of untrammeled fury, and they thrill in the chaos of battle as they allow their Rage to seize and empower them.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'bard'), 'College of Lore', 'college-of-lore', 'Bards of the College of Lore collect spells and secrets from diverse sources, such as scholarly tomes, mystical rites, and peasant tales. The college''s members gather in libraries and universities to share their lore with one another. They also meet at festivals or affairs of state, where they can expose corruption, unravel lies, and poke fun at self-important figures of authority.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'cleric'), 'Life Domain', 'life-domain', 'The Life Domain focuses on the positive energy that helps sustain all life in the multiverse. Clerics who tap into this domain are masters of healing, using that life force to cure many hurts.
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'druid'), 'Circle of the Land', 'circle-of-the-land', 'The Circle of the Land comprises mystics and sages who safeguard ancient knowledge and rites. These Druids meet within sacred circles of trees or standing stones to whisper primal secrets in Druidic. The circle''s wisest members preside as the chief priests of their communities.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'fighter'), 'Champion', 'champion', 'A Champion focuses on the development of martial prowess in a relentless pursuit of victory. Champions combine rigorous training with physical excellence to deal devastating blows, withstand peril, and garner glory. Whether in athletic contests or bloody battle, Champions strive for the crown of the victor.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'monk'), 'Warrior of the Open Hand', 'warrior-of-the-open-hand', 'Warriors of the Open Hand are masters of unarmed combat. They learn techniques to push and trip their opponents and manipulate their own energy to protect themselves from harm.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'paladin'), 'Oath of Devotion', 'oath-of-devotion', 'The Oath of Devotion binds Paladins to the ideals of justice and order. These Paladins meet the archetype of the knight in shining armor. They hold themselves to the highest standards of conduct, and some-for better or worse-hold the rest of the world to the same standards.
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'ranger'), 'Hunter', 'hunter', 'You stalk prey in the wilds and elsewhere, using your abilities as a Hunter to protect nature and people everywhere from forces that would destroy them.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'rogue'), 'Thief', 'thief', 'A mix of burglar, treasure hunter, and explorer, you are the epitome of an adventurer. In addition to improving your agility and stealth, you gain abilities useful for delving into ruins and getting maximum benefit from the magic items you find there.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'sorcerer'), 'Draconic Sorcery', 'draconic-sorcery', 'Your innate magic comes from the gift of a dragon. Perhaps an ancient dragon facing death bequeathed some of its magical power to you or your ancestor. You might have absorbed magic from a site infused with dragons'' power. Or perhaps you handled a treasure taken from a dragon''s hoard that was steeped in draconic power. Or you might have a dragon for an ancestor.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'warlock'), 'Fiend Patron', 'fiend-patron', 'Your pact draws on the Lower Planes, the realms of perdition. You might forge a bargain with a demon lord, an archdevil, or another fiend that is especially mighty. That patron''s aims are evil-the corruption or destruction of all things, ultimately including you-and your path is defined by the extent to which you strive against those aims.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Subclass (classID, subclassName, subclassSlug, subclassDescription, sourceID) VALUES ((SELECT classID FROM Class WHERE classSlug = 'wizard'), 'Evoker', 'evoker', 'Your studies focus on magic that creates powerful elemental effects such as bitter cold, searing flame, rolling thunder, crackling lightning, and burning acid. Some Evokers find employment in military forces, serving as artillery to blast armies from afar. Others use their power to protect others, while some seek their own gain.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-rage', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 1, 'Rage', 'You can imbue yourself with a primal power called Rage, a force that grants you extraordinary might and resilience. You can enter it as a Bonus Action if you aren''t wearing Heavy armor.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-unarmored-defense', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 1, 'Unarmored Defense', 'While you aren''t wearing any armor, your base Ar- mor Class equals 10 plus your Dexterity and Consti- tution modifiers. You can use a Shield and still gain this benefit.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-weapon-mastery', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 1, 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of Simple or Mar- tial Melee weapons of your choice, such as Great- axes and Handaxes. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-danger-sense', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 2, 'Danger Sense', 'You gain an uncanny sense of when things aren''t as they should be, giving you an edge when you dodge perils. You have Advantage on Dexterity saving throws unless you have the Incapacitated condition.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-reckless-attack', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 2, 'Reckless Attack', 'You can throw aside all concern for defense to at- tack with increased ferocity. When you make your first attack roll on your turn, you can decide to at- tack recklessly. Doing so gives you Advantage on at- tack rolls using Strength until the start of your next
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-subclass', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 3, 'Barbarian Subclass', 'You gain a Barbarian subclass of your choice. A subclass is a specialization that grants you features at certain Barbarian levels. For the rest of your career, you gain each of your subclass''s features that are of your Barbarian level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-primal-knowledge', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 3, 'Primal Knowledge', 'You gain proficiency in another skill of your choice from the skill list available to Barbarians at level 1.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Barbarian lev- els 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-extra-attack', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 5, 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-fast-movement', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 5, 'Fast Movement', 'Your speed increases by 10 feet while you aren''t wearing Heavy armor.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-feral-instinct', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 7, 'Feral Instinct', 'Your instincts are so honed that you have Advan- tage on Initiative rolls.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-instinctive-pounce', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 7, 'Instinctive Pounce', 'As part of the Bonus Action you take to enter your Rage, you can move up to half your Speed.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-brutal-strike', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 9, 'Brutal Strike', 'If you use Reckless Attack, you can forgo any Ad- vantage on one Strength-based attack roll of your choice on your turn. The chosen attack roll mustn''t have Disadvantage. If the chosen attack roll hits, the target takes an extra 1d10 damage of the same type dealt by the weapon or Unarmed Strike, and you can cause one Brutal Strike effect of your choice. You have the following effect options.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-relentless-rage', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 11, 'Relentless Rage', 'Your Rage can keep you fighting despite grievous wounds. If you drop to 0 Hit Points while your Rage is active and don''t die outright, you can make a DC 10 Constitution saving throw. If you succeed, your Hit Points instead change to a number equal to twice your Barbarian level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-improved-brutal-strike-1', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 13, 'Improved Brutal Strike', 'You have honed new ways to attack furiously. The following effects are now among your Brutal Strike options.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-persistent-rage', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 15, 'Persistent Rage', 'When you roll Initiative, you can regain all ex- pended uses of Rage. After you regain uses of Rage in this way, you can''t do so again until you finish a Long Rest.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-improved-brutal-strike-2', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 17, 'Improved Brutal Strike', 'The extra damage of your Brutal Strike increases to 2d10. In addition, you can use two different Brutal Strike effects whenever you use your Brutal Strike feature.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-indomitable-might', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 18, 'Indomitable Might', 'If your total for a Strength check or Strength saving throw is less than your Strength score, you can use that score in place of the total.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('barbarian-primal-champion', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), NULL, 20, 'Primal Champion', 'You embody primal power. Your Strength and Con- stitution scores increase by 4, to a maximum of 25.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('berserker-frenzy', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'path-of-the-berserker'), 3, 'Frenzy', 'If you use Reckless Attack while your Rage is active, you deal extra damage to the first target you hit on your turn with a Strength-based attack. To determine the extra damage, roll a number of d6s equal to your Rage Damage bonus, and add them together. The damage has the same type as the weapon or Unarmed Strike used for the attack.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('berserker-mindless-rage', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'path-of-the-berserker'), 6, 'Mindless Rage', 'You have Immunity to the Charmed and Frightened conditions while your Rage is active. If you''re Charmed or Frightened when you enter your Rage, the condition ends on you.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('berserker-retaliation', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'path-of-the-berserker'), 10, 'Retaliation', 'When you take damage from a creature that is within 5 feet of you, you can take a Reaction to make one melee attack against that creature, using a weapon or an Unarmed Strike.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('berserker-intimidating-presence', (SELECT classID FROM Class WHERE classSlug = 'barbarian'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'path-of-the-berserker'), 14, 'Intimidating Presence', 'As a Bonus Action, you can strike terror into others with your menacing presence and primal power.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-bardic-inspiration', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 1, 'Bardic Inspiration', 'You can supernaturally inspire others through words, music, or dance. This inspiration is repre- sented by your Bardic Inspiration die, which is a d6.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 1, 'Spellcasting', 'You have learned to cast spells through your bardic arts. See "Spells" for the rules on spellcasting. The information below details how you use those rules with Bard spells, which appear in the Bard spell list later in the class''s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-expertise', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 2, 'Expertise', 'You gain Expertise (see "Rules Glossary") in two of your skill proficiencies of your choice. Performance and Persuasion are recommended if you have profi- ciency in them.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-jack-of-all-trades', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 2, 'Jack of All Trades', 'You can add half your Proficiency Bonus (round down) to any ability check you make that uses a skill proficiency you lack and that doesn''t otherwise use your Proficiency Bonus.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-subclass', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 3, 'Bard Subclass', 'You gain a Bard subclass of your choice. A subclass is a specialization that grants you features at certain Bard levels. For the rest of your career, you gain each of your subclass''s features that are of your Bard level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-font-of-inspiration', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 5, 'Font of Inspiration', 'You now regain all your expended uses of Bardic In- spiration when you finish a Short or Long Rest.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-countercharm', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 7, 'Countercharm', 'You can use musical notes or words of power to dis- rupt mind-influencing effects. If you or a creature within 30 feet of you fails a saving throw against an effect that applies the Charmed or Frightened con- dition, you can take a Reaction to cause the save to be rerolled, and the new roll has Advantage.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-magical-secrets', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 10, 'Magical Secrets', 'You''ve learned secrets from various magical tradi- tions. Whenever you reach a Bard level (including this level) and the Prepared Spells number in the Bard Features table increases, you can choose any of your new prepared spells from the Bard, Cleric, Druid, and Wizard spell lists, and the chosen spells count as Bard spells for you (see a class''s section for its spell list). In addition, whenever you replace a spell prepared for this class, you can replace it with a spell from those lists.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-superior-inspiration', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 18, 'Superior Inspiration', 'When you roll Initiative, you regain expended uses of Bardic Inspiration until you have two if you have fewer than that.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('bard-words-of-creation', (SELECT classID FROM Class WHERE classSlug = 'bard'), NULL, 20, 'Words of Creation', 'You have mastered two of the Words of Creation: the words of life and death. You therefore always have the Power Word Heal and Power Word Kill spells prepared. When you cast either spell, you can target a second creature with it if that creature is within 10 feet of the first target.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('lore-bonus-proficiencies', (SELECT classID FROM Class WHERE classSlug = 'bard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'college-of-lore'), 3, 'Bonus Proficiencies', 'You gain proficiency with three skills of your choice.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('lore-cutting-words', (SELECT classID FROM Class WHERE classSlug = 'bard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'college-of-lore'), 3, 'Cutting Words', 'You learn to use your wit to supernaturally distract, confuse, and otherwise sap the confidence and com- petence of others. When a creature that you can see within 60 feet of yourself makes a damage roll or succeeds on an ability check or attack roll, you can take a Reaction to expend one use of your Bardic Inspiration; roll your Bardic Inspiration die, and subtract the number rolled from the creature''s roll, reducing the damage or potentially turning the suc- cess into a failure.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('lore-magical-discoveries', (SELECT classID FROM Class WHERE classSlug = 'bard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'college-of-lore'), 6, 'Magical Discoveries', 'You learn two spells of your choice. These spells can come from the Cleric, Druid, or Wizard spell list or any combination thereof (see a class''s section for its spell list). A spell you choose must be a cantrip or a spell for which you have spell slots, as shown in the Bard Features table.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('lore-peerless-skill', (SELECT classID FROM Class WHERE classSlug = 'bard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'college-of-lore'), 14, 'Peerless Skill', 'When you make an ability check or attack roll and fail, you can expend one use of Bardic Inspiration; roll the Bardic Inspiration die, and add the number rolled to the d20, potentially turning a failure into a success. On a failure, the Bardic Inspiration isn''t expended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 1, 'Spellcasting', 'You have learned to cast spells through prayer and meditation. See "Spells" for the rules on spellcasting. The information below details how you use those rules with Cleric spells, which appear on the Cleric spell list later in the class''s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-divine-order', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 1, 'Divine Order', 'You have dedicated yourself to one of the following sacred roles of your choice.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-channel-divinity', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 2, 'Channel Divinity', 'You can channel divine energy directly from the Outer Planes to fuel magical effects. You start with two such effects: Divine Spark and Turn Undead, each of which is described below. Each time you use this class''s Channel Divinity, choose which Channel Divinity effect from this class to create. You gain additional effect options at higher Cleric levels.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-subclass', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 3, 'Cleric Subclass', 'You gain a Cleric subclass of your choice. A subclass is a specialization that grants you features at certain Cleric levels. For the rest of your career, you gain each of your subclass''s features that are of your Cleric level or lower.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-sear-undead', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 5, 'Sear Undead', 'Whenever you use Turn Undead, you can roll a number of d8s equal to your Wisdom modifier (minimum of 1d8) and add the rolls together. Each Undead that fails its saving throw against that use of Turn Undead takes Radiant damage equal to the roll''s total. This damage doesn''t end the turn effect.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-blessed-strikes', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 7, 'Blessed Strikes', 'Divine power infuses you in battle. You gain one of the following options of your choice (if you get either option from a Cleric subclass in an older book, use only the option you choose for this feature).
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-divine-intervention', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 10, 'Divine Intervention', 'You can call on your deity or pantheon to intervene on your behalf. As a Magic action, choose any Cleric spell of level 5 or lower that doesn''t require a
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-improved-blessed-strikes', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 14, 'Improved Blessed Strikes', 'The option you chose for Blessed Strikes grows more powerful.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Fate is recommended.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('cleric-greater-divine-intervention', (SELECT classID FROM Class WHERE classSlug = 'cleric'), NULL, 20, 'Greater Divine Intervention', 'You can call on even more powerful divine intervention. When you use your Divine Intervention feature, you can choose Wish when you select a spell.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('life-disciple-of-life', (SELECT classID FROM Class WHERE classSlug = 'cleric'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'life-domain'), 3, 'Disciple of Life', 'When a spell you cast with a spell slot restores Hit Points to a creature, that creature regains additional Hit Points on the turn you cast the spell. The additional Hit Points equal 2 plus the spell slot''s level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('life-domain-spells', (SELECT classID FROM Class WHERE classSlug = 'cleric'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'life-domain'), 3, 'Life Domain Spells', 'Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Life Domain Spells table, you thereafter always have the listed spells prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('life-preserve-life', (SELECT classID FROM Class WHERE classSlug = 'cleric'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'life-domain'), 3, 'Preserve Life', 'As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to evoke healing energy that can restore a number of Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet of yourself (which can include you), and divide those Hit Points among them. This feature can restore a creature to no more than half its Hit Point maximum.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('life-blessed-healer', (SELECT classID FROM Class WHERE classSlug = 'cleric'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'life-domain'), 6, 'Blessed Healer', 'The healing spells you cast on others heal you as well. Immediately after you cast a spell with a spell slot that restores Hit Points to one or more creatures other than yourself, you regain Hit Points equal to 2 plus the spell slot''s level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('life-supreme-healing', (SELECT classID FROM Class WHERE classSlug = 'cleric'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'life-domain'), 17, 'Supreme Healing', 'When you would normally roll one or more dice to restore Hit Points to a creature with a spell or Channel Divinity, don''t roll those dice for the healing; instead use the highest number possible for each die. For example, instead of restoring 2d6 Hit Points to a creature with a spell, you restore 12.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 1, 'Spellcasting', 'You have learned to cast spells through studying the mystical forces of nature. See "Spells" for the rules on spellcasting. The information below details how you use those rules with Druid spells, which appear on the Druid spell list later in the class''s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-druidic', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 1, 'Druidic', 'You know Druidic, the secret language of Druids. While learning this ancient tongue, you also unlocked the magic of communicating with animals; you always have the Speak with Animals spell prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-primal-order', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 1, 'Primal Order', 'You have dedicated yourself to one of the following sacred roles of your choice.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-wild-shape', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 2, 'Wild Shape', 'The power of nature allows you to assume the form of an animal. As a Bonus Action, you shape-shift into a Beast form that you have learned for this feature (see "Known Forms" below). You stay in that form for a number of hours equal to half your Druid level or until you use Wild Shape again, have the Incapacitated condition, or die. You can also leave the form early as a Bonus Action.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-wild-companion', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 2, 'Wild Companion', 'You can summon a nature spirit that assumes an animal form to aid you. As a Magic action, you can expend a spell slot or a use of Wild Shape to cast the Find Familiar spell without Material components.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-subclass', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 3, 'Druid Subclass', 'You gain a Druid subclass of your choice. A subclass is a specialization that grants you features at certain Druid levels. For the rest of your career, you gain each of your subclass''s features that are of your Druid level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-wild-resurgence', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 5, 'Wild Resurgence', 'Once on each of your turns, if you have no uses of Wild Shape left, you can give yourself one use by expending a spell slot (no action required).
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-elemental-fury', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 7, 'Elemental Fury', 'The might of the elements flows through you. You gain one of the following options of your choice.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-improved-elemental-fury', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 15, 'Improved Elemental Fury', 'The option you chose for Elemental Fury grows more powerful, as detailed below.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-beast-spells', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 18, 'Beast Spells', 'While using Wild Shape, you can cast spells in Beast form, except for any spell that has a Material component with a cost specified or that consumes its Material component.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('druid-archdruid', (SELECT classID FROM Class WHERE classSlug = 'druid'), NULL, 20, 'Archdruid', 'The vitality of nature constantly blooms within you, granting you the following benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('land-circle-of-the-land-spells', (SELECT classID FROM Class WHERE classSlug = 'druid'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'circle-of-the-land'), 3, 'Circle of the Land Spells', 'Whenever you finish a Long Rest, choose one type of land: arid, polar, temperate, or tropical. Consult the table below that corresponds to the chosen type; you have the spells listed for your Druid level and lower prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('land-lands-aid', (SELECT classID FROM Class WHERE classSlug = 'druid'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'circle-of-the-land'), 3, 'Land''s Aid', 'As a Magic action, you can expend a use of your Wild Shape and choose a point within 60 feet of yourself. Vitality-giving flowers and life-draining thorns appear for a moment in a 10-foot-radius Sphere centered on that point. Each creature of your choice in the Sphere must make a Constitution saving throw against your spell save DC, taking 2d6 Necrotic damage on a failed save or half as much damage on a successful one. One creature of your choice in that area regains 2d6 Hit Points.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('land-natural-recovery', (SELECT classID FROM Class WHERE classSlug = 'druid'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'circle-of-the-land'), 6, 'Natural Recovery', 'You can cast one of the level 1+ spells that you have prepared from your Circle Spells feature without expending a spell slot, and you must finish a Long Rest before you do so again.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('land-natures-ward', (SELECT classID FROM Class WHERE classSlug = 'druid'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'circle-of-the-land'), 10, 'Nature''s Ward', 'You are immune to the Poisoned condition, and you have Resistance to a damage type associated with your current land choice in the Circle Spells feature, as shown in the Nature''s Ward table.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('land-natures-sanctuary', (SELECT classID FROM Class WHERE classSlug = 'druid'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'circle-of-the-land'), 14, 'Nature''s Sanctuary', 'As a Magic action, you can expend a use of your Wild Shape and cause spectral trees and vines to appear in a 15-foot Cube on the ground within 120 feet of yourself. They last there for 1 minute or until you have the Incapacitated condition or die. You and your allies have Half Cover while in that area, and your allies gain the current Resistance of your Nature''s Ward while there.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-fighting-style', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 1, 'Fighting Style', 'You have honed your martial prowess and gain a Fighting Style feat of your choice (see "Feats"). Defense is recommended.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-second-wind', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 1, 'Second Wind', 'You have a limited well of physical and mental stamina that you can draw on. As a Bonus Action, you can use it to regain Hit Points equal to 1d10 plus your Fighter level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-weapon-mastery', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 1, 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of three kinds of Simple or Martial weapons of your choice. Whenever you finish
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-action-surge', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 2, 'Action Surge', 'You can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action, except the Magic action.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-tactical-mind', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 2, 'Tactical Mind', 'You have a mind for tactics on and off the battlefield. When you fail an ability check, you can expend a use of your Second Wind to push yourself toward success. Rather than regaining Hit Points, you roll 1d10 and add the number rolled to the ability check, potentially turning it into a success. If the check still fails, this use of Second Wind isn''t expended.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-subclass', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 3, 'Fighter Subclass', 'You gain a Fighter subclass of your choice. A subclass is a specialization that grants you features at certain Fighter levels. For the rest of your career, you gain each of your subclass''s features that are of your Fighter level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-extra-attack', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 5, 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-tactical-shift', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 5, 'Tactical Shift', 'Whenever you activate your Second Wind with a Bonus Action, you can move up to half your Speed without provoking Opportunity Attacks.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-indomitable', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 9, 'Indomitable', 'If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can''t use this feature again until you finish a Long Rest.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-tactical-master', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 9, 'Tactical Master', 'When you attack with a weapon whose mastery property you can use, you can replace that property with the Push, Sap, or Slow property for that attack.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-two-extra-attacks', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 11, 'Two Extra Attacks', 'You can attack three times instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-studied-attacks', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 13, 'Studied Attacks', 'You study your opponents and learn from each attack you make. If you make an attack roll against a creature and miss, you have Advantage on your next attack roll against that creature before the end of your next turn.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Combat Prowess is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fighter-three-extra-attacks', (SELECT classID FROM Class WHERE classSlug = 'fighter'), NULL, 20, 'Three Extra Attacks', 'You can attack four times instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('champion-improved-critical', (SELECT classID FROM Class WHERE classSlug = 'fighter'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'champion'), 3, 'Improved Critical', 'Your attack rolls with weapons and Unarmed Strikes can score a Critical Hit on a roll of 19 or 20 on the d20.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('champion-remarkable-athlete', (SELECT classID FROM Class WHERE classSlug = 'fighter'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'champion'), 3, 'Remarkable Athlete', 'Thanks to your athleticism, you have Advantage on Initiative rolls and Strength (Athletics) checks.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('champion-additional-fighting-style', (SELECT classID FROM Class WHERE classSlug = 'fighter'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'champion'), 7, 'Additional Fighting Style', 'You gain another Fighting Style feat of your choice.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('champion-heroic-warrior', (SELECT classID FROM Class WHERE classSlug = 'fighter'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'champion'), 10, 'Heroic Warrior', 'The thrill of battle drives you toward victory. During combat, you can give yourself Heroic Inspiration whenever you start your turn without it.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('champion-superior-critical', (SELECT classID FROM Class WHERE classSlug = 'fighter'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'champion'), 15, 'Superior Critical', 'Your attack rolls with weapons and Unarmed Strikes can now score a Critical Hit on a roll of 18-20 on the d20.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('champion-survivor', (SELECT classID FROM Class WHERE classSlug = 'fighter'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'champion'), 18, 'Survivor', 'You attain the pinnacle of resilience in battle, giving you these benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-martial-arts', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 1, 'Martial Arts', 'Your practice of martial arts gives you mastery of combat styles that use your Unarmed Strike and Monk weapons, which are the following:
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-unarmored-defense', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 1, 'Unarmored Defense', 'While you aren''t wearing armor or wielding a Shield, your base Armor Class equals 10 plus your Dexterity and Wisdom modifiers.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-monks-focus', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 2, 'Monk''s Focus', 'Your focus and martial training allow you to harness a well of extraordinary energy within yourself. This energy is represented by Focus Points. Your Monk level determines the number of points you have, as shown in the Focus Points column of the Monk Features table.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-unarmored-movement', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 2, 'Unarmored Movement', 'Your speed increases by 10 feet while you aren''t wearing armor or wielding a Shield. This bonus increases when you reach certain Monk levels, as shown on the Monk Features table.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-uncanny-metabolism', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 2, 'Uncanny Metabolism', 'When you roll Initiative, you can regain all expended Focus Points. When you do so, roll your Martial Arts die, and regain a number of Hit Points equal to your Monk level plus the number rolled.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-deflect-attacks', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 3, 'Deflect Attacks', 'When an attack roll hits you and its damage includes Bludgeoning, Piercing, or Slashing damage, you can take a Reaction to reduce the attack''s total damage against you. The reduction equals 1d10 plus your Dexterity modifier and Monk level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-subclass', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 3, 'Monk Subclass', 'You gain a Monk subclass of your choice. A subclass is a specialization that grants you features at certain Monk levels. For the rest of your career, you gain each of your subclass''s features that are of your Monk level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-slow-fall', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 4, 'Slow Fall', 'You can take a Reaction when you fall to reduce any damage you take from the fall by an amount equal to five times your Monk level.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-extra-attack', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 5, 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-stunning-strike', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 5, 'Stunning Strike', 'Once per turn when you hit a creature with a Monk weapon or an Unarmed Strike, you can expend 1 Focus Point to attempt a stunning strike. The target must make a Constitution saving throw. On a failed save, the target has the Stunned condition until the start of your next turn. On a successful save, the target''s Speed is halved until the start of your next turn, and the next attack roll made against the target before then has Advantage.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-empowered-strikes', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 6, 'Empowered Strikes', 'Whenever you deal damage with your Unarmed Strike, it can deal your choice of Force damage or its normal damage type.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-evasion', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 7, 'Evasion', 'When you''re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-acrobatic-movement', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 9, 'Acrobatic Movement', 'While you aren''t wearing armor or wielding a Shield, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the movement.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-heightened-focus', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 10, 'Heightened Focus', 'Your Flurry of Blows, Patient Defense, and Step of the Wind gain the following benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-self-restoration', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 10, 'Self-Restoration', 'Through sheer force of will, you can remove one of the following conditions from yourself at the
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-deflect-energy', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 13, 'Deflect Energy', 'You can now use your Deflect Attacks feature against attacks that deal any damage type, not just Bludgeoning, Piercing, or Slashing.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-disciplined-survivor', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 14, 'Disciplined Survivor', 'Your physical and mental discipline grant you proficiency in all saving throws.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-perfect-focus', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 15, 'Perfect Focus', 'When you roll Initiative and don''t use Uncanny Metabolism, you regain expended Focus Points until you have 4 if you have 3 or fewer.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-superior-defense', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 18, 'Superior Defense', 'At the start of your turn, you can expend 3 Focus Points to bolster yourself against harm for 1 minute or until you have the Incapacitated condition. During that time, you have Resistance to all damage except Force damage.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('monk-body-and-mind', (SELECT classID FROM Class WHERE classSlug = 'monk'), NULL, 20, 'Body and Mind', 'You have developed your body and mind to new heights. Your Dexterity and Wisdom scores increase by 4, to a maximum of 25.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('open-hand-technique', (SELECT classID FROM Class WHERE classSlug = 'monk'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'warrior-of-the-open-hand'), 3, 'Open Hand Technique', 'Whenever you hit a creature with an attack granted by your Flurry of Blows, you can impose one of the following effects on that target.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('open-hand-wholeness-of-body', (SELECT classID FROM Class WHERE classSlug = 'monk'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'warrior-of-the-open-hand'), 6, 'Wholeness of Body', 'You gain the ability to heal yourself. As a Bonus Action, you can roll your Martial Arts die. You regain a number of Hit Points equal to the number rolled plus your Wisdom modifier (minimum of 1 Hit Point regained).
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('open-hand-fleet-step', (SELECT classID FROM Class WHERE classSlug = 'monk'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'warrior-of-the-open-hand'), 11, 'Fleet Step', 'When you take a Bonus Action other than Step of the Wind, you can also use Step of the Wind immediately after that Bonus Action.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('open-hand-quivering-palm', (SELECT classID FROM Class WHERE classSlug = 'monk'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'warrior-of-the-open-hand'), 17, 'Quivering Palm', 'You gain the ability to set up lethal vibrations in someone''s body. When you hit a creature with an Unarmed Strike, you can expend 4 Focus Points to start these imperceptible vibrations, which last for a number of days equal to your Monk level. The vibrations are harmless unless you take an action to end them. Alternatively, when you take the Attack action on your turn, you can forgo one of the attacks to end the vibrations. To end them, you and the target must be on the same plane of existence. When you end them, the target must make a Constitution saving throw, taking 10d12 Force damage on a failed save or half as much damage on a successful one.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-lay-on-hands', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 1, 'Lay On Hands', 'Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you finish a Long Rest. With that pool, you can restore a total number of Hit Points equal to five times your Paladin level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 1, 'Spellcasting', 'You have learned to cast spells through prayer and meditation. See "Spells" for the rules on spellcasting. The information below details how you use those rules with Paladin spells, which appear in the Paladin spell list later in the class''s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-weapon-mastery', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 1, 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longswords and Javelins.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-fighting-style', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 2, 'Fighting Style', 'You gain a Fighting Style feat of your choice (see "Feats" for feats). Instead of choosing one of those feats, you can choose the option below.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-paladins-smite', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 2, 'Paladin''s Smite', 'You always have the Divine Smite spell prepared. In addition, you can cast it without expending a spell slot, but you must finish a Long Rest before you can cast it in this way again.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-channel-divinity', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 3, 'Channel Divinity', 'You can channel divine energy directly from the Outer Planes, using it to fuel magical effects. You start with one such effect: Divine Sense, which is described below. Other Paladin features give additional Channel Divinity effect options. Each time you use this class''s Channel Divinity, you choose which effect from this class to create.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-subclass', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 3, 'Paladin Subclass', 'You gain a Paladin subclass of your choice. A subclass is a specialization that grants you features at certain Paladin levels. For the rest of your career, you gain each of your subclass''s features that are of your Paladin level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-extra-attack', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 5, 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-faithful-steed', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 5, 'Faithful Steed', 'You can call on the aid of an otherworldly steed. You always have the Find Steed spell prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-aura-of-protection', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 6, 'Aura of Protection', 'You radiate a protective, unseeable aura in a 10-foot Emanation that originates from you. The aura is inactive while you have the Incapacitated condition.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-abjure-foes', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 9, 'Abjure Foes', 'As a Magic action, you can expend one use of this class''s Channel Divinity to overwhelm foes with awe. As you present your Holy Symbol or weapon, you can target a number of creatures equal to your Charisma modifier (minimum of one creature) that you can see within 60 feet of yourself. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute or until it takes any damage. While Frightened in this way, a target can do only one of the following on its turns: move, take an action, or take a Bonus Action.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-aura-of-courage', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 10, 'Aura of Courage', 'You and your allies have Immunity to the Frightened condition while in your Aura of Protection. If a Frightened ally enters the aura, that condition has no effect on that ally while there.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-radiant-strikes', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 11, 'Radiant Strikes', 'Your strikes now carry supernatural power. When you hit a target with an attack roll using a Melee weapon or an Unarmed Strike, the target takes an extra 1d8 Radiant damage.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-restoring-touch', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 14, 'Restoring Touch', 'When you use Lay On Hands on a creature, you can also remove one or more of the following conditions from the creature: Blinded, Charmed, Deafened, Frightened, Paralyzed, or Stunned. You must expend 5 Hit Points from the healing pool of Lay On Hands for each of these conditions you remove; those points don''t also restore Hit Points to the creature.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-aura-expansion', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 18, 'Aura Expansion', 'Your Aura of Protection is now a 30-foot Emanation.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('paladin-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'paladin'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Truesight is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('devotion-oath-of-devotion-spells', (SELECT classID FROM Class WHERE classSlug = 'paladin'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'oath-of-devotion'), 3, 'Oath of Devotion Spells', 'The magic of your oath ensures you always have certain spells ready; when you reach a Paladin level specified in the Oath of Devotion Spells table, you thereafter always have the listed spells prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('devotion-sacred-weapon', (SELECT classID FROM Class WHERE classSlug = 'paladin'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'oath-of-devotion'), 3, 'Sacred Weapon', 'When you take the Attack action, you can expend one use of your Channel Divinity to imbue one Melee weapon that you are holding with positive energy. For 10 minutes or until you use this feature again, you add your Charisma modifier to attack rolls you make with that weapon (minimum bonus of +1), and each time you hit with it, you cause it to deal its normal damage type or Radiant damage.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('devotion-aura-of-devotion', (SELECT classID FROM Class WHERE classSlug = 'paladin'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'oath-of-devotion'), 7, 'Aura of Devotion', 'You and your allies have Immunity to the Charmed condition while in your Aura of Protection. If a Charmed ally enters the aura, that condition has no effect on that ally while there.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('devotion-smite-of-protection', (SELECT classID FROM Class WHERE classSlug = 'paladin'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'oath-of-devotion'), 15, 'Smite of Protection', 'Your magical smite now radiates protective energy. Whenever you cast Divine Smite, you and your allies have Half Cover while in your Aura of Protection.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('devotion-holy-nimbus', (SELECT classID FROM Class WHERE classSlug = 'paladin'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'oath-of-devotion'), 20, 'Holy Nimbus', 'As a Bonus Action, you can imbue your Aura of Protection with holy power, granting the benefits below for 10 minutes or until you end them (no action required). Once you use this feature, you can''t use it again until you finish a Long Rest. You can also restore your use of it by expending a level 5 spell slot (no action required).
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 1, 'Spellcasting', 'You have learned to channel the magical essence of nature to cast spells. See "Spells" for the rules on spellcasting. The information below details how you use those rules with Ranger spells, which appear in the Ranger spell list later in the class''s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-favored-enemy', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 1, 'Favored Enemy', 'You always have the Hunter''s Mark spell prepared. You can cast it twice without expending a spell slot, and you regain all expended uses of this ability when you finish a Long Rest.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-weapon-mastery', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 1, 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longbows and Shortswords.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-deft-explorer', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 2, 'Deft Explorer', 'Thanks to your travels, you gain the following benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-fighting-style', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 2, 'Fighting Style', 'You gain a Fighting Style feat of your choice (see "Feats"). Instead of choosing one of those feats, you can choose the option below.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-subclass', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 3, 'Ranger Subclass', 'You gain a Ranger subclass of your choice. A subclass is a specialization that grants you features at certain Ranger levels. For the rest of your career, you gain each of your subclass''s features that are of your Ranger level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-extra-attack', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 5, 'Extra Attack', 'You can attack twice instead of once whenever you take the Attack action on your turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-roving', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 6, 'Roving', 'Your Speed increases by 10 feet while you aren''t wearing Heavy armor. You also have a Climb Speed and a Swim Speed equal to your Speed.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-expertise', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 9, 'Expertise', 'Choose two of your skill proficiencies with which you lack Expertise. You gain Expertise in those skills.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-tireless', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 10, 'Tireless', 'Primal forces now help fuel you on your journeys, granting you the following benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-relentless-hunter', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 13, 'Relentless Hunter', 'Taking damage can''t break your Concentration on Hunter''s Mark.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-natures-veil', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 14, 'Nature''s Veil', 'You invoke spirits of nature to magically hide yourself. As a Bonus Action, you can give yourself the Invisible condition until the end of your next turn.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-precise-hunter', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 17, 'Precise Hunter', 'You have Advantage on attack rolls against the creature currently marked by your Hunter''s Mark.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-feral-senses', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 18, 'Feral Senses', 'Your connection to the forces of nature grants you Blindsight with a range of 30 feet.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('ranger-foe-slayer', (SELECT classID FROM Class WHERE classSlug = 'ranger'), NULL, 20, 'Foe Slayer', 'The damage die of your Hunter''s Mark is a d10 rather than a d6.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('hunter-hunters-lore', (SELECT classID FROM Class WHERE classSlug = 'ranger'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'hunter'), 3, 'Hunter''s Lore', 'You can call on the forces of nature to reveal certain strengths and weaknesses of your prey. While a creature is marked by your Hunter''s Mark, you know whether that creature has any Immunities, Resistances, or Vulnerabilities, and if the creature has any, you know what they are.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('hunter-hunters-prey', (SELECT classID FROM Class WHERE classSlug = 'ranger'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'hunter'), 3, 'Hunter''s Prey', 'You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('hunter-defensive-tactics', (SELECT classID FROM Class WHERE classSlug = 'ranger'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'hunter'), 7, 'Defensive Tactics', 'You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('hunter-superior-hunters-prey', (SELECT classID FROM Class WHERE classSlug = 'ranger'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'hunter'), 11, 'Superior Hunter''s Prey', 'Once per turn when you deal damage to a creature marked by your Hunter''s Mark, you can also deal that spell''s extra damage to a different creature that you can see within 30 feet of the first creature.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('hunter-superior-hunters-defense', (SELECT classID FROM Class WHERE classSlug = 'ranger'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'hunter'), 15, 'Superior Hunter''s Defense', 'When you take damage, you can take a Reaction to give yourself Resistance to that damage and any other damage of the same type until the end of the current turn.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-expertise', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 1, 'Expertise', 'You gain Expertise in two of your skill proficiencies of your choice. Sleight of Hand and Stealth are recommended if you have proficiency in them.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-sneak-attack', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 1, 'Sneak Attack', 'You know how to strike subtly and exploit a foe''s distraction. Once per turn, you can deal an extra 1d6 damage to one creature you hit with an attack roll if you have Advantage on the roll and the attack uses a Finesse or a Ranged weapon. The extra damage''s type is the same as the weapon''s type.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-thieves-cant', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 1, 'Thieves'' Cant', 'You picked up various languages in the communities where you plied your roguish talents. You know Thieves'' Cant and one other language of your choice, which you choose from the language tables in "Character Creation."', 3)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-weapon-mastery', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 1, 'Weapon Mastery', 'Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Daggers and Shortbows.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-cunning-action', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 2, 'Cunning Action', 'Your quick thinking and agility allow you to move and act quickly. On your turn, you can take one of the following actions as a Bonus Action: Dash, Disengage, or Hide.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-subclass', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 3, 'Rogue Subclass', 'You gain a Rogue subclass of your choice. A subclass is a specialization that grants you features at certain Rogue levels. For the rest of your career, you gain each of your subclass''s features that are of your Rogue level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-steady-aim', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 3, 'Steady Aim', 'As a Bonus Action, you give yourself Advantage on your next attack roll on the current turn. You can use this feature only if you haven''t moved during this turn, and after you use it, your Speed is 0 until the end of the current turn.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-cunning-strike', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 5, 'Cunning Strike', 'You''ve developed cunning ways to use your Sneak Attack. When you deal Sneak Attack damage, you can add one of the following Cunning Strike effects.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-uncanny-dodge', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 5, 'Uncanny Dodge', 'When an attacker that you can see hits you with an attack roll, you can take a Reaction to halve the attack''s damage against you (round down).', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-evasion', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 7, 'Evasion', 'You can nimbly dodge out of the way of certain dangers.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-reliable-talent', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 7, 'Reliable Talent', 'Whenever you make an ability check that uses one of your skill or tool proficiencies, you can treat a d20 roll of 9 or lower as a 10.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-improved-cunning-strike', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 11, 'Improved Cunning Strike', 'You can use up to two Cunning Strike effects when you deal Sneak Attack damage, paying the die cost for each effect.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-devious-strikes', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 14, 'Devious Strikes', 'You''ve practiced new ways to use your Sneak Attack deviously. The following effects are now among your Cunning Strike options.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-slippery-mind', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 15, 'Slippery Mind', 'Your cunning mind is exceptionally difficult to control.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-elusive', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 18, 'Elusive', 'You''re so evasive that attackers rarely gain the upper hand against you. No attack roll can have Advantage against you unless you have the Incapacitated condition.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of the Night Spirit is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('rogue-stroke-of-luck', (SELECT classID FROM Class WHERE classSlug = 'rogue'), NULL, 20, 'Stroke of Luck', 'You have a marvelous knack for succeeding when you need to. If you fail a D20 Test, you can turn the roll into a 20.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('thief-fast-hands', (SELECT classID FROM Class WHERE classSlug = 'rogue'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'thief'), 3, 'Fast Hands', 'As a Bonus Action, you can do one of the following.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('thief-second-story-work', (SELECT classID FROM Class WHERE classSlug = 'rogue'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'thief'), 3, 'Second-Story Work', 'You''ve trained to get into especially hard-to-reach places, granting you these benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('thief-supreme-sneak', (SELECT classID FROM Class WHERE classSlug = 'rogue'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'thief'), 9, 'Supreme Sneak', 'You gain the following Cunning Strike option.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('thief-use-magic-device', (SELECT classID FROM Class WHERE classSlug = 'rogue'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'thief'), 13, 'Use Magic Device', 'You''ve learned how to maximize use of magic items, granting you the following benefits.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('thief-thiefs-reflexes', (SELECT classID FROM Class WHERE classSlug = 'rogue'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'thief'), 17, 'Thief''s Reflexes', 'You are adept at laying ambushes and quickly escaping danger. You can take two turns during the first round of any combat. You take your first turn at your normal Initiative and your second turn at your Initiative minus 10.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 1, 'Spellcasting', 'Drawing from your innate magic, you can cast spells. See "Spells" for the rules on spellcasting. The information below details how you use those rules with Sorcerer spells, which appear in the Sorcerer spell list later in the class’s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-innate-sorcery', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 1, 'Innate Sorcery', 'An event in your past left an indelible mark on you, infusing you with simmering magic. As a Bonus Action, you can unleash that magic for 1 minute, during which you gain the following benefits: - The spell save DC of your Sorcerer spells increases by 1.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-font-of-magic', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 2, 'Font of Magic', 'You can tap into the wellspring of magic within yourself. This wellspring is represented by Sorcery Points, which allow you to create a variety of magical effects.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-metamagic', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 2, 'Metamagic', 'Because your magic flows from within, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from "Metamagic Options" later in this class’s description. You use the chosen options to temporarily modify spells you cast. To use an option, you must spend the number of Sorcery Points that it costs.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-subclass', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 3, 'Sorcerer Subclass', 'You gain a Sorcerer subclass of your choice. The Draconic Sorcery subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Sorcerer levels.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-sorcerous-restoration', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 5, 'Sorcerous Restoration', 'When you finish a Short Rest, you can regain expended Sorcery Points, but no more than a number equal to half your Sorcerer level (round down). Once you use this feature, you can’t do so again until you finish a Long Rest.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-sorcery-incarnate', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 7, 'Sorcery Incarnate', 'If you have no uses of Innate Sorcery left, you can use it if you spend 2 Sorcery Points when you take the Bonus Action to activate it.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('sorcerer-arcane-apotheosis', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), NULL, 20, 'Arcane Apotheosis', 'While your Innate Sorcery feature is active, you can use one Metamagic option on each of your turns without spending Sorcery Points on it.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('draconic-sorcery-draconic-resilience', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'draconic-sorcery'), 3, 'Draconic Resilience', 'The magic in your body manifests physical traits of your draconic gift. Your Hit Point maximum increases by 3, and it increases by 1 whenever you gain another Sorcerer level.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('draconic-sorcery-draconic-spells', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'draconic-sorcery'), 3, 'Draconic Spells', 'When you reach a Sorcerer level specified in the Draconic Spells table, you thereafter always have the listed spells prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('draconic-sorcery-elemental-affinity', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'draconic-sorcery'), 6, 'Elemental Affinity', 'Your draconic magic has an affinity with a damage type associated with dragons. Choose one of those types: Acid, Cold, Fire, Lightning, or Poison.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('draconic-sorcery-dragon-wings', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'draconic-sorcery'), 14, 'Dragon Wings', 'As a Bonus Action, you can cause draconic wings to appear on your back. The wings last for 1 hour or until you dismiss them (no action required). For the duration, you have a Fly Speed of 60 feet.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('draconic-sorcery-dragon-companion', (SELECT classID FROM Class WHERE classSlug = 'sorcerer'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'draconic-sorcery'), 18, 'Dragon Companion', 'You can cast Summon Dragon without a Material component. You can also cast it once without a spell slot, and you regain the ability to cast it in this way when you finish a Long Rest.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-eldritch-invocations', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 1, 'Eldritch Invocations', 'You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the "Eldritch Invocation Options" section later in this class''s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-pact-magic', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 1, 'Pact Magic', 'Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-magical-cunning', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 2, 'Magical Cunning', 'You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can''t do so again until you finish a Long Rest.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-subclass', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 3, 'Warlock Subclass', 'You gain a Warlock subclass of your choice. The Fiend Patron subclass is detailed after this class''s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass''s features that are of your Warlock level or lower.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-contact-patron', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 9, 'Contact Patron', 'In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell''s saving throw.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-mystic-arcanum', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 11, 'Mystic Arcanum', 'Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Fate is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('warlock-eldritch-master', (SELECT classID FROM Class WHERE classSlug = 'warlock'), NULL, 20, 'Eldritch Master', 'When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fiend-patron-dark-ones-blessing', (SELECT classID FROM Class WHERE classSlug = 'warlock'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'fiend-patron'), 3, 'Dark One''s Blessing', 'When you reduce an enemy to 0 Hit Points, you gain Temporary Hit Points equal to your Charisma modifier plus your Warlock level (minimum of 1 Temporary Hit Point). You also gain this benefit if someone else reduces an enemy within 10 feet of you to 0 Hit Points.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fiend-patron-fiend-spells', (SELECT classID FROM Class WHERE classSlug = 'warlock'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'fiend-patron'), 3, 'Fiend Spells', 'The magic of your patron ensures you always have certain spells ready; when you reach a Warlock level specified in the Fiend Spells table, you thereafter always have the listed spells prepared.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fiend-patron-dark-ones-own-luck', (SELECT classID FROM Class WHERE classSlug = 'warlock'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'fiend-patron'), 6, 'Dark One''s Own Luck', 'You can call on your fiendish patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add 1d10 to your roll. You can do so after seeing the roll but before any of the roll''s effects occur.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fiend-patron-fiendish-resilience', (SELECT classID FROM Class WHERE classSlug = 'warlock'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'fiend-patron'), 10, 'Fiendish Resilience', 'Choose one damage type, other than Force, whenever you finish a Short or Long Rest. You have Resistance to that damage type until you choose a different one with this feature.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('fiend-patron-hurl-through-hell', (SELECT classID FROM Class WHERE classSlug = 'warlock'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'fiend-patron'), 14, 'Hurl Through Hell', 'Once per turn when you hit a creature with an attack roll, you can try to instantly transport the target through the Lower Planes. The target must succeed on a Charisma saving throw against your spell save DC, or the target disappears and hurtles through a nightmare landscape. The target takes 8d10 Psychic damage if it isn''t a Fiend, and it has the Incapacitated condition until the end of your next turn, when it returns to the space it previously occupied or the nearest unoccupied space.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-spellcasting', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 1, 'Spellcasting', 'As a student of arcane magic, you have learned to cast spells. See "Spells" for the rules on spellcasting.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-ritual-adept', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 1, 'Ritual Adept', 'You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn’t have the spell prepared, but you must read from the book to cast a spell in this way.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-arcane-recovery', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 1, 'Arcane Recovery', 'You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-scholar', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 2, 'Scholar', 'While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-subclass', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 3, 'Wizard Subclass', 'You gain a Wizard subclass of your choice. The Evoker subclass is detailed after this class’s description.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-ability-score-improvement', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 4, 'Ability Score Improvement', 'You gain the Ability Score Improvement feat (see "Feats") or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-memorize-spell', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 5, 'Memorize Spell', 'Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-spell-mastery', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 18, 'Spell Mastery', 'You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-epic-boon', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 19, 'Epic Boon', 'You gain an Epic Boon feat (see "Feats") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('wizard-signature-spells', (SELECT classID FROM Class WHERE classSlug = 'wizard'), NULL, 20, 'Signature Spells', 'Choose two level 3 spells in your spellbook as your signature spells. You always have these spells prepared, and you can cast each of them once at level 3 without expending a spell slot. When you do so, you can’t cast them in this way again until you finish a Short or Long Rest. To cast either spell at a higher level, you must expend a spell slot.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('evoker-evocation-savant', (SELECT classID FROM Class WHERE classSlug = 'wizard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'evoker'), 3, 'Evocation Savant', 'Choose two Wizard spells from the Evocation school, each of which must be no higher than level 2, and add them to your spellbook for free.
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('evoker-potent-cantrip', (SELECT classID FROM Class WHERE classSlug = 'wizard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'evoker'), 3, 'Potent Cantrip', 'Your damaging cantrips affect even creatures that avoid the brunt of the effect. When you cast a cantrip at a creature and you miss with the attack roll or the target succeeds on a saving throw against the cantrip, the target takes half the cantrip’s damage (if any) but suffers no additional effect from the cantrip.', 2)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('evoker-sculpt-spells', (SELECT classID FROM Class WHERE classSlug = 'wizard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'evoker'), 6, 'Sculpt Spells', 'You can create pockets of relative safety within the effects of your evocations. When you cast an Evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 plus the spell’s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('evoker-empowered-evocation', (SELECT classID FROM Class WHERE classSlug = 'wizard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'evoker'), 10, 'Empowered Evocation', 'Whenever you cast a Wizard spell from the Evocation school, you can add your Intelligence modifier to one damage roll of that spell.', 1)
INSERT INTO ClassFeature (featureSlug, classID, subclassID, level, featureName, featureDescription, sortOrder) VALUES ('evoker-overchannel', (SELECT classID FROM Class WHERE classSlug = 'wizard'), (SELECT subclassID FROM Subclass WHERE subclassSlug = 'evoker'), 14, 'Overchannel', 'You can increase the power of your spells. When you cast a Wizard spell with a spell slot of levels 1–5 that deals damage, you can deal maximum damage with that spell on the turn you cast it.
